for lang, (title, subtitle, short, about) in entries.items():
    d['title'][lang] = title
    d['subtitle'][lang] = subtitle
    d['shortDescription'][lang] = short
    sentences = re.split(r'(?<=[.!?])\s+', about)
    split = len(sentences) // 2
    d['aboutBook'][lang] = [' '.join(sentences[:split]), ' '.join(sentences[split:])]
d['shortDescriptionEditorial'] = {'source': 'editorial-review', 'sourceSha256': d['metadataDraft']['sourceSha256']}
d['metadataDraft']['reviewRequired'] = False
p.write_text(json.dumps(d, ensure_ascii=False, indent=2) + '\n')
r = w / 'release.json'
release = json.loads(r.read_text())
release['changes'] = {
    'en': 'First ScriptaHub edition with cleaned English PDF and complete and ten-minute English and Romanian readers.',
    'ro': 'Prima ediție ScriptaHub, cu PDF englez curățat și cititoare integrale și de zece minute în engleză și română.'
}
r.write_text(json.dumps(release, ensure_ascii=False, indent=2) + '\n')
